import zipfile
import xml.etree.ElementTree as ET

NS = '{http://schemas.openxmlformats.org/spreadsheetml/2006/main}'

def cell_text(c):
    t = c.get('t')
    if t == 'inlineStr':
        return ''.join(x.text or '' for x in c.iter(NS + 't'))
    if t == 'b':
        return c.find(NS + 'v').text
    v = c.find(NS + 'v')
    return v.text if v is not None else None

def col_index(ref):
    letters = ''
    for ch in ref:
        if ch.isalpha():
            letters += ch
        else:
            break
    idx = 0
    for ch in letters:
        idx = idx * 26 + (ord(ch.upper()) - 64)
    return idx

with zipfile.ZipFile('budget.xlsx') as z:
    root = ET.fromstring(z.read('xl/worksheets/sheet1.xml'))

rows = {}
for row in root.iter(NS + 'row'):
    r = int(row.get('r'))
    for c in row.findall(NS + 'c'):
        ref = c.get('r')
        val = cell_text(c)
        formula = c.find(NS + 'f')
        ftext = formula.text if formula is not None else None
        rows.setdefault(r, {})[col_index(ref)] = (val, ftext)

def get(row, col):
    cell = rows.get(row, {}).get(col)
    return cell if cell else (None, None)

expense_items = []
for r in range(11, 23):
    cat, _ = get(r, 1)
    sub, _ = get(r, 2)
    amt, _ = get(r, 3)
    if amt is not None:
        expense_items.append((cat, sub, float(amt)))

total = sum(x[2] for x in expense_items)
print("Per-category totals:")
by_cat = {}
for cat, sub, amt in expense_items:
    by_cat[cat] = by_cat.get(cat, 0) + amt
    print(f"  {cat:<15} {sub:<15} {amt:>8.2f}")
for cat, s in by_cat.items():
    print(f"  --- {cat} subtotal: {s:.2f}")
print(f"\nTOTAL EXPENSES (rows 11-22, column C): {total:.2f}")

# Cross-check against the workbook's own formula
f23, _ = get(23, 3)
print("\nWorkbook formula at C23 (Total Expenses):", f23)
f8, _ = get(8, 2)
print("Workbook formula at B8 (Total Income):", f8)
f25, _ = get(25, 2)
print("Workbook formula at B25 (BALANCE):", f25)

